// The playable state: real geography (outline, coast, rivers, lakes, mountains, cities, highways) loaded from
// state.json and compressed by a scale factor, with full-size cities generated by CityLayout. Provides the
// terrain height field the engine builds its landscape from, and merges every city, highway and venue into one
// world CityPlan. World axes: X east, Y south, metres; the start city sits near the origin.
#pragma once

#include "Sim/CityLayout.h"
#include "Sim/Json.h"
#include "Sim/SimCommon.h"

#include <array>
#include <cstddef>
#include <string>
#include <vector>

namespace dtg::sim
{
	using Point2 = std::array<double, 2>;

	struct StateCity
	{
		std::string Name;
		double X = 0.0;
		double Y = 0.0;
		CityStyle Style = CityStyle::Town;
		int Grid = 3;
		bool bStart = false;
		std::vector<std::pair<LotRole, std::string>> Landmarks;
		double LevelM = 0.0;        // ground height the city is built on
		Rect Bounds;                // footprint including its outer roads
	};

	struct StateLake
	{
		std::string Name;
		double X = 0.0;
		double Y = 0.0;
		double RadiusM = 200.0;
		double LevelM = 0.0;        // water surface height
	};

	struct StateRiver
	{
		std::string Name;
		double WidthM = 8.0;
		std::vector<Point2> Points;
	};

	struct StateVenue
	{
		EventKind Kind = EventKind::DragRace;
		std::string Name;
		double X = 0.0;
		double Y = 0.0;
		double LevelM = 0.0;
	};

	/** What lies at a point, for water rendering and gameplay (swimming, bridges). */
	struct SurfaceInfo
	{
		double GroundM = 0.0;
		bool bWater = false;
		double WaterM = 0.0;
		bool bOcean = false;
		double RoadGradeM = 0.0;  // the graded surface a road deck follows (equals GroundM on land)
		bool bRoad = false;       // a highway's carriageway or shoulder runs over this point
		double RoadNearness = 0.0; // 1 on the carriageway, falling to 0 at the far edge of the verge
	};

	class StatePlan
	{
	public:
		bool Load(const JsonValue& Root, std::vector<std::string>& Errors);

		std::string Name;
		std::string Abbreviation;
		double Scale = 25.0;
		double VerticalScale = 3.0;
		double OriginLon = 0.0;
		double OriginLat = 0.0;
		std::vector<Point2> Outline;
		int CoastStart = 0;
		int CoastEnd = 0;
		std::vector<Point2> Mountains;
		double PeakMeters = 1000.0;
		std::vector<StateCity> Cities;
		std::vector<StateLake> Lakes;
		std::vector<StateRiver> Rivers;
		std::vector<HighwayPlan> Highways;
		std::vector<StateVenue> Venues;
		std::vector<VenuePlan> VenueLayouts; // laid out at each venue's final position (same order as Venues)
		Rect Bounds;

		Point2 ToWorld(double Lon, double Lat) const;
		const StateCity* StartCity() const;
		const StateCity* FindCity(const std::string& CityName) const;
		bool InsideState(double X, double Y) const;
		/** Distance to the coastline (metres, world). */
		double CoastDistance(double X, double Y) const;
		/** The side of a town that faces the sea (0 south, 1 east, 2 north, 3 west), or -1 when the sea is not at its edge. */
		int CoastSideOf(const StateCity& City) const;
		/** How far the ground is dug below the pad here by the ditch beside a crossroads community's street; 0 off one. */
		double DitchBesideStreets(double X, double Y) const;
		/** How far a point is out from the asphalt's edge of the nearest crossroads community street (0 on one), or a huge number far from any. */
		double StreetEdgeDistance(double X, double Y) const;
		bool IsOcean(double X, double Y) const;

		/**
		 * The terrain's own value noise, in [-1, 1], at a wavelength in metres. Public because
		 * anything scattered over the land -- trees, scrub -- has to clump where the land does, and
		 * it has to do so from the same seed, or a forest drifts when the state is regenerated.
		 */
		double Noise(double X, double Y, double Wavelength) const;

		/** Terrain height before cities, roads and water are carved in (world metres). */
		double NaturalHeight(double X, double Y) const;
		/** Final ground height: flattened under cities, venues and roads, carved for rivers, lakes and the sea. */
		SurfaceInfo SurfaceAt(double X, double Y) const;
		double HeightAt(double X, double Y) const { return SurfaceAt(X, Y).GroundM; }
		/** Road surface height: a highway's deck profile on a highway, else the ground (or just above water). */
		double RoadHeightAt(double X, double Y) const;

		/**
		 * Discards the lookup grid, so SurfaceAt and RoadHeightAt go back to walking every road and
		 * town in the state. Vastly slower and otherwise identical -- it is the reference the indexed
		 * path is tested against, and the path Load() itself uses while it is still grading the roads.
		 * Rebuilt by the next Load().
		 */
		void ForgetLookup() { Spatial = Lookup(); }

		/**
		 * How many road segments a height query at this point will actually look at. The whole point
		 * of the lookup grid is that this stays a handful rather than every segment in the state, and
		 * it is a count rather than a stopwatch, so a test can hold it to a budget without flaking on
		 * a busy machine. Returns the total segment count when the grid is not built.
		 */
		std::size_t RoadCandidatesAt(double X, double Y) const;

		/** Generates every city and merges them with highways and venues into one world plan. */
		CityPlan BuildWorld(const CityConfig& HubTemplate) const;

	private:
		void PlaceCities();
		void PlaceVenues();
		void DetourAroundCities();
		void JoinCrossings();
		void ComputeDecks();
		void HarmonizeLevels();
		bool FootprintOnLand(const StateCity& City) const;
		/** Inside the level pad of a city or venue. */
		bool InsideFlattened(double X, double Y) const;
		void RouteHighways(const std::vector<std::pair<std::string, std::vector<JsonValue>>>& Routes, const std::vector<bool>& Interstate,
			std::vector<std::string>& Errors);
		Rect CityRect(const StateCity& City, double Margin = 0.0) const;
		/** Distance from a point to a rect (0 inside). */
		static double RectDistance(const Rect& Area, double X, double Y);
		static double SegmentDistance(const Point2& A, const Point2& B, double X, double Y, double* OutT = nullptr);
		/** Height a road is graded to at a polyline vertex: the level of a city or venue it enters, else the land. */
		double AnchorHeight(const Point2& Where) const;
		/**
		 * Cuts and fills every highway to a grade a road can actually be built at.
		 *
		 * Without this a road is pinned to the terrain at each of its own vertices and simply follows
		 * the hillside between them, which is fine across a coastal plain and absurd in a mountain
		 * range -- North Carolina's US-64 came out climbing at 56%. Heights inside a town are pinned,
		 * because the road has to meet the streets; everything between them is free to be dug out of
		 * the hill or carried across it on an embankment.
		 */
		void GradeHighways();
		/** Nearest point on the state outline. */
		Point2 NearestBorderPoint(double X, double Y) const;

		/**
		 * A uniform grid over every highway segment and every town, built once the world is laid out.
		 *
		 * The terrain is a function, and that function is asked for a height a few million times a
		 * minute: sixty-seven squared samples per streamed chunk, two chunks a frame, plus every wheel
		 * of every car on the road. Walking all hundred and forty-one road segments and all
		 * twenty-five towns for each of those is what decides whether there is any frame budget left
		 * for the world to look like anything.
		 */
		struct Lookup
		{
			static constexpr double CellM = 400.0;
			std::vector<std::vector<int>> RoadCells;
			/** Distance along each road at each of its points, so a segment's offset is not re-walked. */
			std::vector<std::vector<double>> RoadStartM;  // packed segment ids: Road index << 12 | segment
			std::vector<std::vector<int>> TownCells;  // city indices
			double OriginX = 0.0;
			double OriginY = 0.0;
			int Stride = 0;
			int Rows = 0;

			bool Ready() const { return Stride > 0 && Rows > 0; }
			int CellFor(double X, double Y) const;
			/** Every cell within Radius of a point, appended to Out. */
			void CellsNear(double X, double Y, double RadiusM, std::vector<int>& Out) const;
		};
		void BuildLookup();
		Lookup Spatial;

		std::uint64_t Seed = 1977;
	};

	/** Block pitch used for every city (block + road), so city footprints can be computed before generation. */
	double CitySpan(int Grid, double BlockSize = 110.0, double RoadWidth = 18.0);
	/**
	 * How wide a town's streets are, kerb to kerb, by its style: a crossroads community has two lanes
	 * and shoulders (10 m), a town twelve, a city or resort strip fourteen, the hub its five lanes (18).
	 */
	double RoadWidthFor(CityStyle Style);
}
